public static boolean isJDK14() {
        ClassLoader loader = getClassLoader(ObjectUtilities.class);
        if (loader != null) {
            try {
              loader.loadClass("java.util.RandomAccess");
              return true;
            }
            catch (ClassNotFoundException e) {
              return false;
            }
            catch(Exception e) {
              // do nothing, but do not crash ...
            }
        }
        // OK, the quick and dirty, but secure way failed. Lets try it
        // using the standard way.
        try {
            String version = System.getProperty(
                    "java.vm.specification.version");
            // parse the beast...
            if (version == null) {
                return false;
            }

            String[] versions = parseVersions(version);
            String[] target = new String[]{ "1", "4" };
            return (ArrayUtilities.compareVersionArrays(versions, target) >= 0);
        }
        catch(Exception e) {
            return false;
        }
    }

public static Point getCenterPoint ()
    {
      GraphicsEnvironment localGraphicsEnvironment 
              = GraphicsEnvironment.getLocalGraphicsEnvironment();
      try {
          Method method = GraphicsEnvironment.class.getMethod("getCenterPoint", 
                  (Class[]) null);
          return (Point) method.invoke(localGraphicsEnvironment, 
                  (Object[]) null);
      }
      catch (Exception e) {
        // ignore ... will fail if this is not a JDK 1.4 ..
      }

      Dimension s = Toolkit.getDefaultToolkit().getScreenSize();
      return new Point (s.width / 2, s.height / 2);
    }

